{"script":"raw = repo.read("deploy.json")
data = json.decode(raw)
targets = []
for t in data.get("targets", []):
    if t.get("env") == "prod":
        targets.append(t)
targets = sorted(targets, key = lambda t: t["name"])
names = [t["name"] for t in targets]
total = 0
for t in targets:
    total += t["replicas"]
ov = repo.read("overrides.json", missing_ok = True)
return {
    "prod_target_names": names,
    "total_replicas": total,
    "overrides_present": ov != None,
    "all_targets": data.get("targets"),
    "overrides_content": ov,
}
"}
